/**
 * Event tools: list, get, create, update, delete.
 * Zod shapes mirror src/app/api/admin/events/route.ts (create) and
 * events/[id]/route.ts (update). Slug is generated by the server and cannot be edited.
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { apiRequest, fail, failFromApi, guard, ok, unwrap, type ApiResult } from "../client.js";

const EVENT_TYPES = ["MEETUP", "WORKSHOP", "CAREER_TALK", "HACKATHON", "CONFERENCE", "CONVERSATIONS"] as const;
const EVENT_STATUSES = ["UPCOMING", "REGISTRATION_OPEN", "SOLD_OUT", "COMPLETED", "CANCELLED"] as const;
const AUDIENCES = ["dev", "non_tech_pro", "student", "founder", "creator"] as const;
const INTENTS = ["learn_basics", "find_event", "find_collaborators", "build", "hire_or_partner", "other"] as const;

/** Create fields, same constraints as the route's eventSchema. */
const eventFields = {
  title: z.string().min(3).max(200).describe("Event title (3-200 chars)"),
  description: z.string().min(10).max(500).describe("Short description (10-500 chars)"),
  fullDescription: z.string().max(5000).optional().describe("Long description (max 5000 chars). Cannot be cleared once set."),
  date: z.string().datetime().describe("Start date-time, ISO 8601 UTC with Z, e.g. 2026-11-07T06:00:00.000Z"),
  time: z.string().max(50).describe("Display time text, e.g. '9:00 AM - 1:00 PM EAT'"),
  venue: z.string().max(200).describe("Venue name"),
  city: z.string().max(100).describe("City, e.g. Nairobi"),
  type: z.enum(EVENT_TYPES).describe("Event type"),
  status: z.enum(EVENT_STATUSES).describe("Event status"),
  registrationUrl: z.string().url().optional().describe("Registration link"),
  lumaUrl: z.string().url().optional().describe("Luma event link"),
  host: z.string().max(200).optional().describe("Host name"),
  partnerOrg: z.string().max(200).optional().describe("Partner organisation"),
  highlights: z.array(z.string().max(200)).optional().describe("Highlight bullets (each max 200 chars)"),
  agenda: z.array(z.string().max(200)).optional().describe("Agenda items (each max 200 chars)"),
  attendeeCount: z.number().int().min(0).optional().describe("Actual attendee count"),
  capacity: z.number().int().min(0).optional().describe("Seat cap"),
  posterUrl: z.string().url().optional().describe("Poster image URL (see upload_image)"),
  photosUrl: z.string().url().optional().describe("External photos album URL"),
  featured: z.boolean().optional().describe("Feature on the site (default false)"),
  audiences: z.array(z.enum(AUDIENCES)).optional().describe("Target audiences"),
  intents: z.array(z.enum(INTENTS)).optional().describe("Matching intents"),
};

/** Update fields: every create field optional, minus photosUrl (not in the update route), posterUrl nullable. */
const { photosUrl: _photosUrl, posterUrl: _posterUrl, ...updatableFields } = eventFields;
const eventUpdateFields = {
  ...z.object(updatableFields).partial().shape,
  posterUrl: z.string().url().nullable().optional().describe("Poster image URL, or null to clear"),
};

const updateObject = z.object(eventUpdateFields);
export type EventPatch = z.infer<typeof updateObject>;

/** PATCH an event. Shared with event_set_poster. */
export async function patchEvent(id: string, patch: EventPatch): Promise<ApiResult> {
  return apiRequest("PATCH", `/api/admin/events/${encodeURIComponent(id)}`, { json: patch });
}

interface EventRow {
  id?: string;
  slug?: string;
  title?: string;
  date?: string;
  city?: string;
  status?: string;
  type?: string;
  featured?: boolean;
  posterUrl?: string | null;
}

/** Compact row for list output (full records come from events_get). */
function slimEvent(row: EventRow): EventRow {
  const { id, slug, title, date, city, status, type, featured, posterUrl } = row;
  return { id, slug, title, date, city, status, type, featured, posterUrl };
}

/** Register the event tools on the server. */
export function registerEventTools(server: McpServer): void {
  server.registerTool(
    "events_list",
    {
      title: "List events",
      description:
        "List events, newest first, as compact rows (id, slug, title, date, city, status, type). The server paginates but cannot filter, so status/city filters apply only to the fetched page; use events_get for a full record.",
      inputSchema: {
        page: z.number().int().min(1).default(1).describe("Page number (default 1)"),
        limit: z.number().int().min(1).max(100).default(20).describe("Rows per page (default 20)"),
        status: z.enum(EVENT_STATUSES).optional().describe("Keep only this status (client-side, current page)"),
        city: z.string().optional().describe("Keep only this city, case-insensitive (client-side, current page)"),
      },
      annotations: { readOnlyHint: true, openWorldHint: true },
    },
    guard("events_list", async ({ page, limit, status, city }) => {
      const res = await apiRequest("GET", "/api/admin/events", { query: { page, limit } });
      if (!res.ok) return failFromApi("Listing events", res);
      const body = res.data as { data?: EventRow[]; pagination?: { total: number; pages: number } };
      let rows = body.data ?? [];
      if (status) rows = rows.filter((e) => e.status === status);
      if (city) rows = rows.filter((e) => e.city?.toLowerCase() === city.toLowerCase());
      const p = body.pagination;
      const summary = `${rows.length} event(s) on page ${page}${p ? ` of ${p.pages} (${p.total} total)` : ""}.`;
      return ok(summary, { events: rows.map(slimEvent), pagination: p });
    }),
  );

  server.registerTool(
    "events_get",
    {
      title: "Get event",
      description: "Fetch one event with all fields by its id.",
      inputSchema: { id: z.string().min(1).describe("Event id (cuid), from events_list") },
      annotations: { readOnlyHint: true, openWorldHint: true },
    },
    guard("events_get", async ({ id }) => {
      const res = await apiRequest("GET", `/api/admin/events/${encodeURIComponent(id)}`);
      if (!res.ok) return failFromApi("Fetching event", res);
      const event = unwrap(res) as EventRow;
      return ok(`Event "${event.title}" (${event.status}, ${event.city}, ${event.date}).`, event);
    }),
  );

  server.registerTool(
    "events_create",
    {
      title: "Create event",
      description: "Create an event. The slug is generated from the title and cannot be changed later.",
      inputSchema: eventFields,
      annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: true },
    },
    guard("events_create", async (input) => {
      const res = await apiRequest("POST", "/api/admin/events", { json: input });
      if (!res.ok) return failFromApi("Creating event", res);
      const event = unwrap(res) as EventRow;
      return ok(`Created event "${event.title}" with id ${event.id}, slug ${event.slug}.`, event);
    }),
  );

  server.registerTool(
    "events_update",
    {
      title: "Update event",
      description: "Update an event by id. Send only the fields to change. The slug is not editable.",
      inputSchema: { id: z.string().min(1).describe("Event id (cuid)"), ...eventUpdateFields },
      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: true, openWorldHint: true },
    },
    guard("events_update", async ({ id, ...patch }) => {
      if (Object.keys(patch).length === 0) return fail("No fields to update were provided.");
      const res = await patchEvent(id, patch);
      if (!res.ok) return failFromApi("Updating event", res);
      const event = unwrap(res) as EventRow;
      return ok(`Updated event "${event.title}" (fields: ${Object.keys(patch).join(", ")}).`, event);
    }),
  );

  server.registerTool(
    "events_delete",
    {
      title: "Delete event",
      description: "Permanently delete an event. Refuses unless confirm is true.",
      inputSchema: {
        id: z.string().min(1).describe("Event id (cuid)"),
        confirm: z.boolean().describe("Must be true to delete; any other value refuses"),
      },
      annotations: { readOnlyHint: false, destructiveHint: true, openWorldHint: true },
    },
    guard("events_delete", async ({ id, confirm }) => {
      if (confirm !== true) return fail("Refusing to delete: confirm must be true.");
      const res = await apiRequest("DELETE", `/api/admin/events/${encodeURIComponent(id)}`);
      if (!res.ok) return failFromApi("Deleting event", res);
      return ok(`Deleted event ${id}.`, res.data);
    }),
  );
}
